# Generates every invitation asset through the Higgsfield CLI, in canon order.
#
# Generated by tools/handoff.ts from tools/art-direction.ts -- do not edit by hand.
# Re-run `npm run handoff` after changing the canon.
#
# Prerequisites:  npm install -g @higgsfield/cli  &&  higgsfield auth login
# Run from the tools/ directory:  .\generate-on-windows.ps1

$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path -Parent $PSScriptRoot
$mediaRoot = Join-Path $repoRoot 'public/invitation/higgsfield'

function Invoke-Asset {
    param(
        [string]$Id,
        [string]$Destination,
        [string[]]$CliArgs
    )

    if (Test-Path $Destination) {
        Write-Host "skip   $Id (already on disk)" -ForegroundColor DarkGray
        return
    }

    Write-Host "generate  $Id" -ForegroundColor Cyan
    $raw = & higgsfield @CliArgs --json
    if ($LASTEXITCODE -ne 0) {
        Write-Host "  the CLI reported an error for $Id; stopping" -ForegroundColor Red
        exit 1
    }

    # Pull the first URL out of the response, whatever key the CLI wraps it in.
    $url = $null
    try {
        $parsed = $raw | ConvertFrom-Json
        foreach ($key in @('result_url', 'url', 'output_url')) {
            if ($parsed.PSObject.Properties.Name -contains $key -and $parsed.$key) {
                $url = $parsed.$key; break
            }
        }
    } catch { }
    if (-not $url) {
        $match = [regex]::Match([string]$raw, 'https://[^"\s]+\.(png|jpg|jpeg|webp|mp4)')
        if ($match.Success) { $url = $match.Value }
    }

    if (-not $url) {
        Write-Host "  finished, but no download URL was found in the response." -ForegroundColor Yellow
        Write-Host "  save it manually to: $Destination" -ForegroundColor Yellow
        Write-Host $raw
        return
    }

    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Destination) | Out-Null
    Invoke-WebRequest -Uri $url -OutFile $Destination
    Write-Host "  saved  $Destination" -ForegroundColor Green
}

# --- The hero comes first and alone: everything else is judged against it. ---

Invoke-Asset -Id 'fairytale-castle-hero-mobile' `

Write-Host ''
Write-Host 'The hero is done. Send it over for sign-off before generating the rest.' -ForegroundColor Yellow
$answer = Read-Host 'Continue with the remaining 16 assets now? (y/N)'
if ($answer -ne 'y') { Write-Host 'Stopped. Re-run this script to pick up where it left off.'; exit 0 }

